<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{createColumn,deleteColumn,listColumns,updateColumn,type CmsColumn,type ColumnDraft}from'../../api/columns';type Node=CmsColumn&{children:Node[]};const columns=ref<CmsColumn[]>([]),loading=ref(false),dialogVisible=ref(false),saving=ref(false),editingId=ref<number|null>(null);const form=reactive<ColumnDraft>({parentId:null,name:'',alias:'',sortOrder:0,enabled:true});const treeRows=computed<Node[]>(()=>{const m=new Map<number,Node>();columns.value.forEach(i=>m.set(i.id,{...i,children:[]}));const roots:Node[]=[];m.forEach(n=>{if(n.parentId!=null&&m.has(n.parentId))m.get(n.parentId)!.children.push(n);else roots.push(n)});const sort=(a:Node[])=>{a.sort((x,y)=>x.sortOrder-y.sortOrder||x.id-y.id);a.forEach(x=>sort(x.children))};sort(roots);return roots});const parentOptions=computed(()=>columns.value.filter(i=>i.id!==editingId.value));onMounted(refresh);async function refresh(){loading.value=true;try{columns.value=await listColumns()}catch(e){ElMessage.error(msg(e))}finally{loading.value=false}}function openCreate(parentId:number|null=null){editingId.value=null;Object.assign(form,{parentId,name:'',alias:'',sortOrder:0,enabled:true});dialogVisible.value=true}function openEdit(r:CmsColumn){editingId.value=r.id;Object.assign(form,{parentId:r.parentId,name:r.name,alias:r.alias,sortOrder:r.sortOrder,enabled:r.enabled});dialogVisible.value=true}async function save(){if(!form.name.trim()){ElMessage.warning('请输入栏目名称');return}saving.value=true;try{editingId.value==null?await createColumn({...form}):await updateColumn(editingId.value,{...form});dialogVisible.value=false;await refresh()}catch(e){ElMessage.error(msg(e))}finally{saving.value=false}}async function toggle(r:CmsColumn,enabled:boolean){try{await updateColumn(r.id,{parentId:r.parentId,name:r.name,alias:r.alias,sortOrder:r.sortOrder,enabled});await refresh()}catch(e){ElMessage.error(msg(e))}}async function remove(r:CmsColumn){try{await ElMessageBox.confirm(`确定删除栏目“${r.name}”吗？`,'删除栏目',{type:'warning'});await deleteColumn(r.id);await refresh()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}}const msg=(e:unknown)=>e instanceof Error?e.message:'操作失败'</script><template><main class="admin-shell"><header class="page-header"><div><p class="eyebrow">网站内容</p><h1>栏目管理</h1><p class="subtitle">维护普通信息发布栏目、稳定 Alias、层级和状态。</p></div><el-button data-testid="add-column" type="primary" @click="openCreate()">新增栏目</el-button></header><el-card shadow="never"><el-table v-loading="loading" :data="treeRows" row-key="id" default-expand-all><el-table-column prop="name" label="栏目名称" min-width="220"/><el-table-column prop="alias" label="Alias" min-width="180"/><el-table-column prop="sortOrder" label="排序" width="90"/><el-table-column label="状态" width="130"><template #default="s"><el-switch :model-value="s.row.enabled" :data-testid="`enabled-${s.row.id}`" active-text="启用" inactive-text="停用" @change="v=>toggle(s.row,v===true)"/></template></el-table-column><el-table-column label="操作" width="230"><template #default="s"><el-button link type="primary" @click="openCreate(s.row.id)">新增子栏目</el-button><el-button :data-testid="`edit-${s.row.id}`" link type="primary" @click="openEdit(s.row)">编辑</el-button><el-button :data-testid="`delete-${s.row.id}`" link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="dialogVisible" :title="editingId==null?'新增栏目':'编辑栏目'" width="520px"><el-form label-width="90px"><el-form-item label="栏目名称" required><el-input v-model="form.name" placeholder="请输入栏目名称"/></el-form-item><el-form-item label="Alias"><el-input v-model="form.alias" placeholder="留空时自动生成兼容别名"/></el-form-item><el-form-item label="上级栏目"><el-select v-model="form.parentId" clearable style="width:100%"><el-option v-for="i in parentOptions" :key="i.id" :label="i.name" :value="i.id"/></el-select></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="dialogVisible=false">取消</el-button><el-button data-testid="save-column" type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></main></template>
